import { ViewTransition } from 'react'
import './transitions.css'

/**
 * The connector: give the same `id` to an element on two routes and the browser
 * morphs one into the other across the navigation.
 *
 *   // /gallery
 *   <Connector id={`card-${p.id}`}><Card /></Connector>
 *   // /gallery/[id]
 *   <Connector id={`card-${p.id}`}><Hero /></Connector>
 *
 * Ids must be unique per page — two live elements sharing one id cancels the morph.
 * Takes exactly one child element.
 */
export function Connector({
  id,
  children,
}: {
  id: string
  children: React.ReactNode
}) {
  return (
    <ViewTransition name={id} share="t-connector" default="none">
      {children}
    </ViewTransition>
  )
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

.transition-overlay svg {
  width: 100%;
  height: 100%;
}

/* ---------- crayon ---------- */

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

/* Hidden until the first leave phase measures the real path lengths. */
.transition-overlay path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- connector (view-transitions type) ---------- */

:root {
  --t-duration: 320ms;
  --t-ease: cubic-bezier(0.32, 0.72, 0, 1);
}

::view-transition-group(.t-connector),
::view-transition-old(.t-connector),
::view-transition-new(.t-connector) {
  animation-duration: var(--t-duration);
  animation-timing-function: var(--t-ease);
}

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 1ms !important;
    animation-delay: 0s !important;
  }
  /* Overlay transitions skip animating entirely — see transition-core.tsx. */
  .transition-overlay {
    display: none;
  }
}
